solution:
import kotlinx.coroutines.*

suspend fun loadPrice(name: String): Int {
    delay(10)
    return name.length * 10
}

suspend fun total(): Int {
    val bread = loadPrice("хлеб")
    val cheese = loadPrice("сыр")
    return bread + cheese
}

